import {assetRetryUrl,reportAssetFailure,reportAssetSuccess} from './asset-recovery.js';
const aborted=()=>Object.assign(new Error('Asset load cancelled'),{name:'AbortError'});
function wait(ms,signal){return new Promise((resolve,reject)=>{if(signal?.aborted)return reject(aborted());const abort=()=>{clearTimeout(timer);reject(aborted());},timer=setTimeout(()=>{signal?.removeEventListener('abort',abort);resolve();},ms);signal?.addEventListener('abort',abort,{once:true});});}
async function attempts(url,load,{signal,retries=2,retry=0}={}){let error;for(let i=0;i<=retries;i++){if(signal?.aborted)throw aborted();if(i)await wait([250,1000][Math.min(i-1,1)],signal);try{const image=await load(i+retry?assetRetryUrl(url,i+retry):url,signal);reportAssetSuccess(url);return image;}catch(e){error=e;if(e.name==='AbortError'||signal?.aborted)throw aborted();if(e.retryable===false)break;}}if(!(error instanceof Error))error=Error(String(error));error.assetUrl=url;reportAssetFailure(url,error);throw error;}
export function loadImageAsset(url,options={}){return attempts(url,(source,signal)=>new Promise((resolve,reject)=>{const img=new Image();let done=false;const finish=(error)=>{if(done)return;done=true;clearTimeout(timer);signal?.removeEventListener('abort',abort);img.onload=img.onerror=null;if(error){try{img.src='';}catch{}reject(error);}else resolve(img);},abort=()=>finish(aborted()),timer=setTimeout(()=>finish(Error('Image load timed out: '+url)),15000);signal?.addEventListener('abort',abort,{once:true});img.onload=()=>{if(typeof img.decode!=='function')finish();};img.onerror=()=>finish(Error('Image failed: '+url));try{img.src=source;if(typeof img.decode==='function')img.decode().then(()=>finish(),finish);}catch(error){finish(error);}}),options);}
